17	package org.springframework.samples.petclinic.rest.controller.v1;
18	
19	import java.time.LocalDate;
20	import java.util.Collection;
21	import java.util.List;
22	import java.util.Optional;
23	import java.util.concurrent.atomic.AtomicLong;
24	
25	import org.slf4j.Logger;
26	import org.slf4j.LoggerFactory;
27	import tools.jackson.databind.ObjectMapper;
28	import tools.jackson.databind.json.JsonMapper;
29	import org.springframework.http.HttpHeaders;
30	import org.springframework.http.HttpStatus;
31	import org.springframework.http.ResponseEntity;
32	import org.springframework.samples.petclinic.mapper.OwnerMapper;
33	import org.springframework.samples.petclinic.mapper.PetMapper;
34	import org.springframework.samples.petclinic.mapper.VisitMapper;
35	import org.springframework.samples.petclinic.model.Owner;
36	import org.springframework.samples.petclinic.model.Pet;
37	import org.springframework.samples.petclinic.model.Visit;
38	import org.springframework.samples.petclinic.rest.api.OwnersApi;
39	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
40	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
41	import org.springframework.samples.petclinic.rest.dto.PetDto;
42	import org.springframework.samples.petclinic.rest.dto.PetFieldsDto;
43	import org.springframework.samples.petclinic.rest.dto.VisitDto;
44	import org.springframework.samples.petclinic.rest.dto.VisitFieldsDto;
45	import org.springframework.samples.petclinic.service.ClinicService;
46	import org.springframework.samples.petclinic.service.IdempotencyStore;
47	import org.springframework.samples.petclinic.util.BusinessDays;
48	import org.springframework.security.access.prepost.PreAuthorize;
49	import org.springframework.web.bind.annotation.CrossOrigin;
50	import org.springframework.web.bind.annotation.RequestMapping;
51	import org.springframework.web.bind.annotation.RestController;
52	import org.springframework.web.util.UriComponentsBuilder;
53	
54	import jakarta.servlet.http.HttpServletRequest;
55	import jakarta.transaction.Transactional;
56	
57	/**
58	 * @author Vitaliy Fedoriv
59	 */
60	
61	@RestController
62	@CrossOrigin(exposedHeaders = "errors, content-type")
63	@RequestMapping("/api")
64	public class OwnerRestControllerV1 implements OwnersApi {
65	
66	    /** Dedicated audit logger: on a successful create an audit line records the owner id,
67	     * customerCode and registrationDate. */
68	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
69	
70	    /** Serializes the structured {@link OwnerCreatedEvent} emitted on each create. */
71	    private static final ObjectMapper AUDIT_MAPPER = JsonMapper.builder().build();
72	
73	    /** Monotonically increasing sequence number assigned to each successful create's audit event. */
74	    private static final AtomicLong AUDIT_EVENT_SEQ = new AtomicLong();
75	
76	    /** Maximum number of owners permitted in a single city; the create is rejected at this count. */
77	    private static final int CITY_CAPACITY = 50;
78	
79	    /** Maximum number of owners that may be created on a single day (by registrationDate); the
80	     * create is rejected once this many owners already carry today's registration date. */
81	    private static final int DAILY_REGISTRATION_LIMIT = 100;
82	
83	    /** Once more than this many owners already carry a given day's registration date, a new owner
84	     * created for that day is flagged with {@code bulkSignupWarning} to signal a bulk-signup surge. */
85	    private static final int BULK_SIGNUP_WARNING_THRESHOLD = 80;
86	
87	    /** HTTP header carrying the client-supplied idempotency key for a create. */
88	    private static final String IDEMPOTENCY_KEY_HEADER = "Idempotency-Key";
89	
90	    private final ClinicService clinicService;
91	
92	    private final OwnerMapper ownerMapper;
93	
94	    private final PetMapper petMapper;
95	
96	    private final VisitMapper visitMapper;
97	
98	    private final HttpServletRequest request;
99	
100	    private final IdempotencyStore idempotencyStore;
101	
102	    public OwnerRestControllerV1(ClinicService clinicService,
103	                                 OwnerMapper ownerMapper,
104	                                 PetMapper petMapper,
105	                                 VisitMapper visitMapper,
106	                                 HttpServletRequest request,
107	                                 IdempotencyStore idempotencyStore) {
108	        this.clinicService = clinicService;
109	        this.ownerMapper = ownerMapper;
110	        this.petMapper = petMapper;
111	        this.visitMapper = visitMapper;
112	        this.request = request;
113	        this.idempotencyStore = idempotencyStore;
114	    }
115	
116	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
117	    @Override
118	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
119	        Collection<Owner> owners;
120	        if (lastName != null) {
121	            owners = this.clinicService.findOwnerByLastName(lastName);
122	        } else {
123	            owners = this.clinicService.findAllOwners();
124	        }
125	        if (owners.isEmpty()) {
126	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
127	        }
128	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
129	    }
130	
131	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
132	    @Override
133	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
134	        Owner owner = this.clinicService.findOwnerById(ownerId);
135	        if (owner == null) {
136	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
137	        }
138	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
139	    }
140	
141	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
142	    @Override
143	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
144	        // Idempotent create: if this request carries an Idempotency-Key we have already created an
145	        // owner for, return that original owner with 200 OK instead of creating a duplicate.
146	        String idempotencyKey = request.getHeader(IDEMPOTENCY_KEY_HEADER);
147	        boolean hasIdempotencyKey = idempotencyKey != null && !idempotencyKey.isBlank();
148	        if (hasIdempotencyKey) {
149	            Optional<Owner> existing = this.idempotencyStore.find(idempotencyKey)
150	                .map(this.clinicService::findOwnerById);
151	            if (existing.isPresent()) {
152	                return new ResponseEntity<>(ownerMapper.toOwnerDto(existing.get()), HttpStatus.OK);
153	            }
154	        }
155	        HttpHeaders headers = new HttpHeaders();
156	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
157	        // The effective registration date (supplied, or the server date when omitted) must fall on
158	        // a business day: a weekend rolls forward to the next Monday. Everything derived from the
159	        // registration date — the stored value, the per-day limit below and the membership number —
160	        // uses this adjusted date.
161	        LocalDate effectiveDate = BusinessDays.effectiveRegistrationDate(owner.getRegistrationDate());
162	        owner.setRegistrationDate(effectiveDate);
163	        // Per-day capacity: once the day has reached its limit of newly created owners, reject
164	        // further creates for that day with 429 Too Many Requests.
165	        int ownersRegisteredToday = this.clinicService.countOwnersRegisteredOn(effectiveDate);
166	        if (ownersRegisteredToday >= DAILY_REGISTRATION_LIMIT) {
167	            return new ResponseEntity<>(HttpStatus.TOO_MANY_REQUESTS);
168	        }
169	        // Bulk-signup warning: flag this owner when more than 80 owners have already been created
170	        // for its registration date, signalling a bulk-signup surge.
171	        owner.setBulkSignupWarning(ownersRegisteredToday > BULK_SIGNUP_WARNING_THRESHOLD);
172	        // Per-city capacity: a city that already holds the maximum number of owners is full.
173	        if (this.clinicService.countOwnersInCity(owner.getCity()) >= CITY_CAPACITY) {
174	            return new ResponseEntity<>(HttpStatus.CONFLICT);
175	        }
176	        // The household id is derived deterministically on the owner itself (see
177	        // Owner.getHouseholdId()) from its normalized last name and postcode, so owners sharing a
178	        // last name and postcode share it automatically — no linking step and no ordering to manage.
179	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
180	        // Exact-identity hard duplicate: reject with 409 when the new owner's WHOLE identityKey
181	        // (the SHA-256 of normalized telephone | lower-cased email-or-empty | soundex(lastName))
182	        // equals an existing owner's. A truly identical record is always rejected, independent of
183	        // sharesHousehold.
184	        if (this.clinicService.isIdentityKeyInUse(owner)) {
185	            return new ResponseEntity<>(HttpStatus.CONFLICT);
186	        }
187	        // Household membership: another owner may already belong to this (last name, postcode)
188	        // household. A new member is admitted rather than rejected — its membership level is instead
189	        // capped relative to the household (see below). An undeclared member (sharesHousehold not
190	        // set) that is not an exact-identity duplicate is still allowed through, flagged as a
191	        // possible duplicate for review.
192	        boolean householdInUse = this.clinicService.isHouseholdInUse(owner);
193	        // Soft "possible duplicate" detection: an existing owner's last name has the same Soundex
194	        // code and the same postcode, while its identity key differs (so it is not a hard
195	        // duplicate). A declared household member (sharesHousehold on an in-use household) is an
196	        // intentional share, not a suspected duplicate, so it is not flagged; otherwise the create
197	        // still proceeds, flagged with possibleDuplicate=true and possibleDuplicateOf set to the
198	        // matching owner id.
199	        Integer possibleDuplicateOf = (householdInUse && sharesHousehold)
200	            ? null
201	            : this.clinicService.findPossibleDuplicateOwnerId(owner);
202	        owner.setPossibleDuplicate(possibleDuplicateOf != null);
203	        owner.setPossibleDuplicateOf(possibleDuplicateOf);
204	        owner.setNamesakeCount(
205	            this.clinicService.countNamesakes(owner.getFirstName(), owner.getLastName()));
206	        // Membership-level ceiling: a new owner's membershipLevel may not exceed one above the
207	        // current maximum level among its existing household members. Derive the cap from those
208	        // members' effective (already-capped) levels; with no existing member the cap stays null
209	        // and the owner's level is used uncapped.
210	        Collection<Owner> householdMembers = this.clinicService.findHouseholdMembers(owner);
211	        if (!householdMembers.isEmpty()) {
212	            int maxHouseholdLevel = householdMembers.stream()
213	                .mapToInt(member -> ownerMapper.formatMembershipLevel(member))
214	                .max()
215	                .getAsInt();
216	            owner.setMembershipLevelCap(maxHouseholdLevel + 1);
217	        }
218	        this.clinicService.saveOwner(owner);
219	        // Compute the derived membership level once so the human-readable line and the structured
220	        // event below are guaranteed to report the identical value.
221	        int membershipLevel = ownerMapper.formatMembershipLevel(owner);
222	        AUDIT.info("owner created id={} customerCode={} registrationDate={} membershipLevel={} membershipNumber={}",
223	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
224	            membershipLevel, ownerMapper.formatMembershipNumber(owner));
225	        // In addition to the human-readable audit line above, emit an immutable structured event.
226	        // The event carries the owner's current primary identifier (today the customerCode, later the
227	        // memberId) via Owner.getPrimaryIdentifier(), and a sequence number that strictly increases
228	        // across creates.
229	        OwnerCreatedEvent event = new OwnerCreatedEvent(
230	            AUDIT_EVENT_SEQ.incrementAndGet(), owner.getId(), owner.getPrimaryIdentifier(),
231	            membershipLevel, OwnerCreatedEvent.EVENT_TYPE);
232	        AUDIT.info(AUDIT_MAPPER.writeValueAsString(event));
233	        if (hasIdempotencyKey) {
234	            this.idempotencyStore.record(idempotencyKey, owner.getId());
235	        }
236	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
237	        headers.setLocation(UriComponentsBuilder.newInstance()
238	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
239	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
240	    }
241	
242	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
243	    @Override
244	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
245	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
246	        if (currentOwner == null) {
247	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
248	        }
249	        currentOwner.setAddressLine1(ownerMapper.normalizeAddress(ownerFieldsDto.getAddressLine1()));
250	        currentOwner.setAddressLine2(ownerMapper.normalizeAddress(ownerFieldsDto.getAddressLine2()));
251	        currentOwner.setAddress(ownerMapper.composeAddress(ownerFieldsDto));
252	        currentOwner.setCity(ownerFieldsDto.getCity());
253	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
254	        currentOwner.setLastName(ownerFieldsDto.getLastName());
255	        currentOwner.setTelephone(ownerMapper.normalizeTelephone(ownerFieldsDto.getTelephone()));
256	        currentOwner.setEmail(ownerMapper.normalizeEmail(ownerFieldsDto.getEmail()));
257	        currentOwner.setPostcode(ownerFieldsDto.getPostcode());
258	        this.clinicService.saveOwner(currentOwner);
259	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
260	    }
261	
262	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
263	    @Transactional
264	    @Override
265	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
266	        Owner owner = this.clinicService.findOwnerById(ownerId);
267	        if (owner == null) {
268	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
269	        }
270	        this.clinicService.deleteOwner(owner);
271	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
272	    }
273	
274	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
275	    @Override
276	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
277	        Owner owner = this.clinicService.findOwnerById(ownerId);
278	        if (owner == null) {
279	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
280	        }
281	        HttpHeaders headers = new HttpHeaders();
282	        Pet pet = petMapper.toPet(petFieldsDto);
283	        owner.setId(ownerId);
284	        pet.setOwner(owner);
285	        pet.getType().setName(null);
286	        this.clinicService.savePet(pet);
287	        PetDto petDto = petMapper.toPetDto(pet);
288	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
289	            .buildAndExpand(pet.getId()).toUri());
290	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
291	    }
292	
293	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
294	    @Override
295	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
296	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
297	        if (currentOwner != null) {
298	            Pet currentPet = this.clinicService.findPetById(petId);
299	            if (currentPet != null) {
300	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
301	                currentPet.setName(petFieldsDto.getName());
302	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
303	                this.clinicService.savePet(currentPet);
304	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
305	            }
306	        }
307	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
308	    }
309	
310	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
311	    @Override
312	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
313	        HttpHeaders headers = new HttpHeaders();
314	        Visit visit = visitMapper.toVisit(visitFieldsDto);
315	        Pet pet = new Pet();
316	        pet.setId(petId);
317	        visit.setPet(pet);
318	        this.clinicService.saveVisit(visit);
319	        VisitDto visitDto = visitMapper.toVisitDto(visit);
320	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
321	            .buildAndExpand(visit.getId()).toUri());
322	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
323	    }
324	
325	
326	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
327	    @Override
328	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
329	        Owner owner = this.clinicService.findOwnerById(ownerId);
330	        if (owner != null) {
