45	     * Resolve an owner's possible-duplicate flag, coalescing a {@code null} stored value
46	     * (e.g. for owners created before the flag existed) to {@code false} so the response
47	     * always carries an explicit boolean.
48	     */
49	    default Boolean formatPossibleDuplicate(Owner owner) {
50	        if (owner == null) {
51	            return null;
52	        }
53	        return Boolean.TRUE.equals(owner.getPossibleDuplicate());
54	    }
55	
56	    /**
57	     * Derive an owner's age band from its {@code birthDate}, measured as the owner's age in whole
58	     * years on its {@code registrationDate}: {@code "MINOR"} when under 18, {@code "ADULT"} from 18
59	     * through 64, and {@code "SENIOR"} at 65 and over. Returns {@code null} when the owner, its
60	     * birth date or its registration date is absent, since the band cannot be derived without both
61	     * dates.
62	     */
63	    default String formatAgeBand(Owner owner) {
64	        if (owner == null || owner.getBirthDate() == null || owner.getRegistrationDate() == null) {
65	            return null;
66	        }
67	        int age = java.time.Period.between(owner.getBirthDate(), owner.getRegistrationDate()).getYears();
68	        if (age < 18) {
69	            return "MINOR";
70	        }
71	        if (age < 65) {
72	            return "ADULT";
73	        }
74	        return "SENIOR";
75	    }
76	
77	    /**
78	     * Derive an owner's preferred contact channel from its stored contact details:
79	     * {@code "EMAIL"} when a (non-blank) email address is present, otherwise {@code "PHONE"}.
80	     */
81	    default String formatContactPreference(Owner owner) {
82	        if (owner == null) {
83	            return null;
84	        }
85	        boolean hasEmail = owner.getEmail() != null && !owner.getEmail().isEmpty();
86	        return hasEmail ? "EMAIL" : "PHONE";
87	    }
88	
89	    /**
90	     * Resolve an owner's bulk-signup warning flag, coalescing a {@code null} stored value
91	     * (e.g. for owners created before the flag existed) to {@code false} so the response
92	     * always carries an explicit boolean.
93	     */
94	    default Boolean formatBulkSignupWarning(Owner owner) {
95	        if (owner == null) {
96	            return null;
97	        }
98	        return Boolean.TRUE.equals(owner.getBulkSignupWarning());
99	    }
100	
101	    /**
102	     * Derive an owner's locality from its region-and-hash identity: the {@code <REGION>} segment
103	     * of the {@code customerCode} (the part before the first hyphen), which is the region code
104	     * derived from the owner's postcode. For an owner that has not yet been assigned a customer
105	     * code, the region is derived directly from the postcode (see {@link Regions#forPostcode}),
106	     * yielding the same value the code would carry. Returns {@code null} only when the owner
107	     * itself is {@code null}.
108	     */
109	    default String formatLocality(Owner owner) {
110	        if (owner == null) {
111	            return null;
112	        }
113	        String code = owner.getCustomerCode();
114	        if (code != null) {
115	            int hyphen = code.indexOf('-');
116	            return hyphen >= 0 ? code.substring(0, hyphen) : code;
117	        }
118	        return Regions.forPostcode(owner.getPostcode());
119	    }
120	
121	    /**
122	     * Derive an owner's timezone as the IANA name mapped from its locality/region via a fixed
123	     * region-to-timezone table (see {@link Regions#timezoneForRegion}): NSW -> Australia/Sydney,
124	     * VIC -> Australia/Melbourne, QLD -> Australia/Brisbane. Returns {@code null} when the owner
125	     * is {@code null} or its region is not in the table.
126	     */
127	    default String formatTimezone(Owner owner) {
128	        if (owner == null) {
129	            return null;
130	        }
131	        return Regions.timezoneForRegion(formatLocality(owner));
132	    }
133	
134	    /**
135	     * Compute an owner's membership points. Points start at {@code 0} and gain: {@code 2} when an
136	     * email address is present; {@code 1} when the owner has no namesakes (its
137	     * {@code namesakeCount} is {@code 0}); {@code 2} for a household of three or more members (the
138	     * owner plus its pets); and {@code 3} when the owner's tenure (the number of fiscal years
139	     * elapsed since its {@code registrationDate}'s fiscal year) exceeds {@code 1}. A null or absent
140	     * namesake count is treated as not being zero, so it contributes nothing.
141	     */
142	    default Integer formatMembershipPoints(Owner owner) {
143	        if (owner == null) {
144	            return null;
145	        }
146	        int points = 0;
147	        boolean hasEmail = owner.getEmail() != null && !owner.getEmail().isEmpty();
148	        if (hasEmail) {
149	            points += 2;
150	        }
151	        boolean uniqueName = owner.getNamesakeCount() != null && owner.getNamesakeCount() == 0;
152	        if (uniqueName) {
153	            points += 1;
154	        }
155	        int householdSize = 1 + (owner.getPets() == null ? 0 : owner.getPets().size());
156	        if (householdSize >= 3) {
157	            points += 2;
158	        }
159	        LocalDate registrationDate = owner.getRegistrationDate();
160	        if (registrationDate != null
161	            && fiscalYearEndYear(LocalDate.now()) - fiscalYearEndYear(registrationDate) > 1) {
162	            points += 3;
163	        }
164	        return points;
165	    }
166	
167	    /**
168	     * Determine an owner's membership level, a number from {@code 1} to {@code 4} derived from its
169	     * membership points (see {@link #formatMembershipPoints(Owner)}): level {@code 1} for
170	     * {@code 0}-{@code 1} points, {@code 2} for {@code 2}-{@code 3}, {@code 3} for {@code 4}-{@code 5}
171	     * and {@code 4} for {@code 6} or more.
172	     *
173	     * <p>The level is then capped by the owner's {@code membershipLevelCap} when one is present (see
174	     * {@link Owner#getMembershipLevelCap()}): a new owner's level may not exceed one above the
175	     * current maximum level among its existing household members, so the returned value is the
176	     * smaller of the points-derived level and the cap. A {@code null} cap means no household ceiling
177	     * applies and the points-derived level is returned unchanged.
178	     */
179	    default Integer formatMembershipLevel(Owner owner) {
180	        if (owner == null) {
181	            return null;
182	        }
183	        int points = formatMembershipPoints(owner);
184	        int level;
185	        if (points <= 1) {
186	            level = 1;
187	        }
188	        else if (points <= 3) {
189	            level = 2;
190	        }
191	        else if (points <= 5) {
192	            level = 3;
193	        }
194	        else {
195	            level = 4;
196	        }
197	        Integer cap = owner.getMembershipLevelCap();
198	        if (cap != null && cap < level) {
199	            return cap;
200	        }
201	        return level;
202	    }
203	
204	    /**
205	     * Compute an owner's check digit: a single Luhn check digit (0-9) over the digits
206	     * contained in the owner's {@code customerCode}. Non-digit characters (the region segment
207	     * and any hex letters of the hash) are ignored. Returns {@code null} when the owner or its
208	     * customer code is absent, since the digit cannot be derived without the code.
209	     */
210	    default Integer formatCheckDigit(Owner owner) {
211	        if (owner == null || owner.getCustomerCode() == null) {
212	            return null;
213	        }
214	        String code = owner.getCustomerCode();
215	        int sum = 0;
216	        boolean dbl = true;
217	        for (int i = code.length() - 1; i >= 0; i--) {
218	            char c = code.charAt(i);
219	            if (c < '0' || c > '9') {
220	                continue;
221	            }
222	            int d = c - '0';
223	            if (dbl) {
224	                d *= 2;
225	                if (d > 9) {
226	                    d -= 9;
227	                }
228	            }
229	            sum += d;
230	            dbl = !dbl;
231	        }
232	        return (10 - (sum % 10)) % 10;
233	    }
234	
235	    /**
236	     * Format an owner's membership number as {@code "<customerCode>-M<YY>"}, where {@code YY}
237	     * is the last two digits of the owner's fiscal year (see {@link #formatFiscalYear(Owner)}),
238	     * the fiscal year of the business-day-adjusted registration date (e.g.
239	     * {@code "NSW-3F5A9C2E-M26"}). Returns {@code null} when either the customer code or
240	     * registration date is absent, since the number cannot be derived without both.
241	     */
242	    default String formatMembershipNumber(Owner owner) {
243	        if (owner == null || owner.getCustomerCode() == null || owner.getRegistrationDate() == null) {
244	            return null;
245	        }
246	        return String.format("%s-M%02d", owner.getCustomerCode(),
247	            fiscalYearEndYear(owner.getRegistrationDate()) % 100);
248	    }
249	
250	    /**
251	     * Format an owner's fiscal year as {@code "FY<YY>"}, where {@code YY} is the last two digits
252	     * of the fiscal year its (business-day-adjusted) {@code registrationDate} falls in (e.g.
253	     * {@code "FY26"}). The fiscal year starts on 1 July and is named by the calendar year in
254	     * which it ends, so a registration date of {@code 2026-07-01} is {@code "FY27"} while
255	     * {@code 2026-06-30} is {@code "FY26"}. Returns {@code null} when the owner or its
256	     * registration date is absent.
257	     */
258	    default String formatFiscalYear(Owner owner) {
259	        if (owner == null || owner.getRegistrationDate() == null) {
260	            return null;
261	        }
262	        return String.format("FY%02d", fiscalYearEndYear(owner.getRegistrationDate()) % 100);
263	    }
264	
265	    /**
266	     * The calendar year in which {@code date}'s fiscal year ends, used as the fiscal year's name.
267	     * The fiscal year starts on 1 July, so a date in July through December belongs to the fiscal
268	     * year ending the following calendar year, while January through June belongs to the one
269	     * ending in the current calendar year.
270	     */
271	    default int fiscalYearEndYear(LocalDate date) {
272	        return date.getMonthValue() >= java.time.Month.JULY.getValue() ? date.getYear() + 1 : date.getYear();
273	    }
274	
275	    /**
276	     * Format an owner's stored E.164 telephone for humans as the country code, a space, then the
277	     * national digits grouped in threes, e.g. {@code "+61412345678"} becomes
278	     * {@code "+61 412 345 678"} (see {@link E164Telephone#toDisplay}). The raw {@code telephone}
279	     * is left in E.164 form. Returns {@code null} when the owner or its telephone is absent.
280	     */
281	    default String formatTelephoneDisplay(Owner owner) {
282	        if (owner == null) {
283	            return null;
284	        }
285	        return E164Telephone.toDisplay(owner.getTelephone());
286	    }
287	
288	    /**
289	     * Compose an owner's salutation as its {@code title} followed by a single space and the
290	     * last name (e.g. {@code "DR Franklin"}). When no title was supplied (null or blank) the
291	     * salutation is just the last name. Returns {@code null} when the owner is {@code null}.
292	     */
293	    default String formatSalutation(Owner owner) {
294	        if (owner == null) {
295	            return null;
296	        }
297	        String title = owner.getTitle();
298	        if (title == null || title.trim().isEmpty()) {
299	            return owner.getLastName();
300	        }
301	        return title + " " + owner.getLastName();
302	    }
303	
304	    /**
305	     * Build a link to an owner's own resource, formed as {@code "/api/owners/"} followed by the
306	     * owner's id. Returns {@code null} when the owner or its id is absent, since the link cannot
307	     * be formed without an id.
308	     */
309	    default String formatSelfLink(Owner owner) {
310	        if (owner == null || owner.getId() == null) {
311	            return null;
312	        }
313	        return "/api/owners/" + owner.getId();
314	    }
315	
316	    /**
317	     * Format an owner's name as {@code "LastName, FirstName"} from the stored names.
318	     */
319	    default String formatDisplayName(Owner owner) {
320	        if (owner == null) {
321	            return null;
322	        }
323	        return owner.getLastName() + ", " + owner.getFirstName();
324	    }
325	
326	    /**
327	     * Format an owner's initials as the upper-cased first letters of the first and last
328	     * names, dot-separated with a trailing dot, e.g. {@code "J.S."}.
329	     */
330	    default String formatInitials(Owner owner) {
331	        if (owner == null) {
332	            return null;
333	        }
334	        return Character.toUpperCase(owner.getFirstName().charAt(0)) + "."
335	            + Character.toUpperCase(owner.getLastName().charAt(0)) + ".";
336	    }
337	
338	    Owner toOwner(OwnerDto ownerDto);
339	
340	    @Mapping(target = "id", ignore = true)
341	    @Mapping(target = "pets", ignore = true)
342	    @Mapping(target = "namesakeCount", ignore = true)
343	    @Mapping(target = "bulkSignupWarning", ignore = true)
344	    @Mapping(target = "possibleDuplicate", ignore = true)
345	    @Mapping(target = "possibleDuplicateOf", ignore = true)
346	    @Mapping(target = "membershipLevelCap", ignore = true)
347	    @Mapping(target = "address", expression = "java(composeAddress(ownerDto))")
348	    @Mapping(target = "addressLine1", source = "addressLine1", qualifiedByName = "normalizeAddress")
349	    @Mapping(target = "addressLine2", source = "addressLine2", qualifiedByName = "normalizeAddress")
350	    @Mapping(target = "telephone", source = "telephone", qualifiedByName = "normalizeTelephone")
351	    @Mapping(target = "email", source = "email", qualifiedByName = "normalizeEmail")
352	    Owner toOwner(OwnerFieldsDto ownerDto);
353	
354	    /**
355	     * Normalize a postal address for storage into its canonical form (see
356	     * {@link AddressNormalizer}), so it is persisted and returned the same way regardless of
357	     * the formatting supplied by the caller. {@code @Named} keeps this out of MapStruct's
358	     * automatic method selection, so it only runs where a mapping explicitly references it via
359	     * {@code qualifiedByName}.
360	     */
361	    @Named("normalizeAddress")
362	    default String normalizeAddress(String address) {
363	        return AddressNormalizer.normalize(address);
364	    }
365	
366	    /**
367	     * Compose the single stored/returned {@code address} from whichever address fields the request
368	     * supplies, preferring the structured form. When a non-blank {@code addressLine1} is present the
369	     * composed value is the normalized {@code addressLine1} (see {@link AddressNormalizer}), with a
370	     * single space and the normalized {@code addressLine2} appended when {@code addressLine2} is
371	     * present; otherwise it falls back to the normalized flat {@code address}. This keeps everything
372	     * that reads the stored address consistent regardless of which form the caller used.
373	     */
374	    default String composeAddress(OwnerFieldsDto ownerDto) {
375	        if (ownerDto == null) {
376	            return null;
377	        }
378	        String line1 = ownerDto.getAddressLine1();
379	        if (line1 != null && !line1.trim().isEmpty()) {
380	            String composed = AddressNormalizer.normalize(line1);
381	            String line2 = ownerDto.getAddressLine2();
382	            if (line2 != null && !line2.trim().isEmpty()) {
383	                composed = composed + " " + AddressNormalizer.normalize(line2);
384	            }
385	            return composed;
386	        }
387	        return AddressNormalizer.normalize(ownerDto.getAddress());
388	    }
389	
390	    /**
391	     * Normalize a telephone number for storage into E.164 form (see {@link E164Telephone}).
392	     * The requirement that a valid E.164 number can be formed is enforced separately by
393	     * {@code TelephoneValidation}, so for already-validated input this returns the E.164
394	     * string; it is idempotent, so re-normalizing a stored value yields the same value.
395	     * {@code @Named} keeps this out of MapStruct's automatic method selection, so it only
396	     * runs where a mapping explicitly references it via {@code qualifiedByName}.
397	     */
398	    @Named("normalizeTelephone")
399	    default String normalizeTelephone(String telephone) {
400	        return E164Telephone.normalize(telephone);
401	    }
402	
403	    /**
404	     * Normalize an email address for storage by lower-casing it, so it is persisted and
405	     * returned in a canonical form regardless of the casing supplied by the caller.
406	     * Syntactic validity is enforced separately by the {@code @Email} constraint on the DTO.
407	     * {@code @Named} keeps this out of MapStruct's automatic method selection, so it only
408	     * runs where a mapping explicitly references it via {@code qualifiedByName}.
409	     */
410	    @Named("normalizeEmail")
411	    default String normalizeEmail(String email) {
412	        return email == null ? null : email.toLowerCase();
413	    }
414	
415	    List<OwnerDto> toOwnerDtoCollection(Collection<Owner> ownerCollection);
416	
417	    Collection<Owner> toOwners(Collection<OwnerDto> ownerDtos);
418	
419	    default OwnerPageDto toOwnerPageDto(@NonNull Page<Owner> ownerPage) {
420	        OwnerPageDto ownerPageDto = new OwnerPageDto();
421	        ownerPageDto.setContent(toOwnerDtoCollection(ownerPage.getContent()));
422	        ownerPageDto.setPage(ownerPage.getNumber());
423	        ownerPageDto.setSize(ownerPage.getSize());
424	        ownerPageDto.setTotalElements(ownerPage.getTotalElements());
425	        ownerPageDto.setTotalPages(ownerPage.getTotalPages());
426	        return ownerPageDto;
427	    }
428	}
